head.b:skin:
/* ILLUMINISMO — tokens (STYLE.md §1–3) */
:root{--bg:#11110f;--panel:#1a1a16;--line:#37362c;--gold:#d5b978;--text:#f1eee4;--muted:#aaa79a;--paper:#e8dfc9;--ink:#272720;
--serif:Georgia,"Noto Serif Georgian",serif;--sans:Arial,"Noto Sans Georgian",sans-serif;color-scheme:dark}
*{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);line-height:1.8;font-size:16px}
a{color:inherit;text-decoration:none}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:4px}
img{max-width:100%;height:auto}
h1,h2,h3{font-family:var(--serif);font-weight:400}
h1{font-size:clamp(2.1rem,4.1vw,4.2rem);line-height:1.3;letter-spacing:-.035em;margin:.2em 0 .5em}
h2{font-size:1.9rem;line-height:1.45}h3{font-size:1.35rem}
.skip{position:absolute;left:-999px;top:8px;background:var(--gold);color:#161610;padding:8px 14px;z-index:99}.skip:focus{left:8px}
.wrap{max-width:1480px;margin:auto;padding:0 5%}
/* header */
.site-header{border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(17,17,15,.94);backdrop-filter:blur(6px);z-index:20}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:18px;padding-bottom:18px;flex-wrap:wrap}
.brand{display:flex;align-items:center;gap:14px;font-family:var(--serif);font-size:1.2rem;letter-spacing:.15em;line-height:1.3}
.brand-mark{border:1px solid var(--gold);width:32px;height:42px;display:grid;place-items:center;color:var(--gold);font-size:1.55rem}
.brand small{display:block;font-family:var(--sans);letter-spacing:.12em;color:var(--muted);font-size:.7rem;margin-top:4px}
.menu ul{list-style:none;display:flex;gap:22px;margin:0;padding:0;flex-wrap:wrap}
.menu a{color:var(--muted);font-size:.9rem;padding:6px 0;border-bottom:1px solid transparent}.menu a:hover,.menu a.active{color:var(--gold);border-color:var(--gold)}
.tools{display:flex;gap:12px;align-items:center}
.search-form{display:flex;border:1px solid var(--line)}.search-form input{background:transparent;border:0;color:var(--text);padding:8px 10px;width:150px;font-family:var(--sans)}
.search-form button{background:transparent;border:0;color:var(--gold);padding:0 10px;cursor:pointer}
.lang button{background:transparent;border:1px solid var(--line);color:var(--muted);padding:6px 10px;cursor:pointer;font-size:.8rem}.lang button[aria-pressed=true]{color:var(--gold);border-color:var(--gold)}
/* progress (F-PROGRESS) */
#read-progress{position:fixed;top:0;left:0;height:2px;background:var(--gold);width:0;z-index:30}
/* text */
.eyebrow{text-transform:uppercase;color:var(--gold);font-size:.8rem;letter-spacing:.08em;margin:0 0 14px}
.lede{font-size:1.08rem;color:#c7c4b6;max-width:680px;line-height:1.95}
.gold{display:inline-block;background:var(--gold);color:#161610;border:1px solid var(--gold);padding:13px 20px;font-weight:600;font-size:.9rem;min-height:48px}
.quiet{color:var(--gold);border-bottom:1px solid var(--line);font-size:.9rem}
.muted{color:var(--muted)}
/* hero */
.hero{padding:70px 0 50px;border-bottom:1px solid var(--line)}
.hero h1{max-width:900px}
/* section */
.section{padding:56px 0;border-bottom:1px solid var(--line)}
.section-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin-bottom:26px;flex-wrap:wrap}
.section-head h2{margin:0}
/* works gallery (F-CATALOG) */
.filters{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 22px}
.filters button{background:transparent;border:1px solid var(--line);color:var(--muted);padding:6px 12px;font-size:.82rem;cursor:pointer}
.filters button[aria-pressed=true]{color:var(--gold);border-color:var(--gold)}
.works{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:20px}
.work{background:var(--panel);border:1px solid var(--line);display:flex;flex-direction:column;transition:border-color .2s}
.work:hover{border-color:var(--gold)}
.work img{aspect-ratio:1200/630;object-fit:cover;width:100%;display:block;background:#000}
.work-body{padding:16px 18px 20px}.work-body h3{margin:4px 0 6px}.work-body p{margin:0;color:var(--muted);font-size:.92rem}
.work .tag{font-size:.72rem;color:var(--gold);text-transform:uppercase;letter-spacing:.08em}
/* post cards */
.posts{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:26px}
.card{border-top:1px solid var(--line);padding-top:18px}
.card img{width:100%;aspect-ratio:16/9;object-fit:cover;border:1px solid var(--line);margin-bottom:14px;display:block}
.card h3{margin:2px 0 8px;font-size:1.4rem;line-height:1.4}.card h3 a:hover{color:var(--gold)}
.card p{color:#c7c4b6;margin:0 0 10px;font-size:.95rem}
.meta{color:var(--muted);font-size:.82rem;display:flex;gap:14px;flex-wrap:wrap}
/* article */
.article{max-width:760px;margin:0 auto;padding:56px 0 30px}
.article-head{margin-bottom:30px}
.post-body{font-family:var(--serif);font-size:1.12rem;line-height:1.95}
.post-body > p:first-of-type::first-letter{float:left;font-size:3.6rem;line-height:1;padding:8px 12px 0 0;color:var(--gold)}
.post-body h2{font-size:1.65rem;margin:2em 0 .6em}.post-body h3{margin:1.6em 0 .5em}
.post-body a{color:var(--gold);border-bottom:1px solid var(--line)}
.post-body blockquote{margin:1.6em 0;padding:4px 0 4px 22px;border-left:2px solid var(--gold);color:#d9d5c6}
.post-body img{border:1px solid var(--line)}
.post-body figure{margin:1.8em 0}.post-body figcaption{font-family:var(--sans);color:var(--muted);font-size:.82rem}
.post-body table{border-collapse:collapse;width:100%;font-family:var(--sans);font-size:.92rem}.post-body th,.post-body td{border-bottom:1px solid var(--line);padding:8px;text-align:left}
/* evidence (F-EVIDENCE · research machine) */
.fact,.interp{font-family:var(--sans);font-size:.95rem;padding:14px 18px;margin:1.4em 0;border:1px solid var(--line);background:var(--panel)}
.fact::before{content:"წყარო · Source";display:block;color:var(--gold);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px}
.interp{border-style:dashed}.interp::before{content:"ინტერპრეტაცია · Interpretation";display:block;color:var(--muted);font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px}
.ev{display:inline-block;font-family:var(--sans);font-size:.7rem;border:1px solid var(--gold);color:var(--gold);padding:0 6px;margin-left:4px;vertical-align:middle}
.sources{font-family:var(--sans);font-size:.88rem;color:var(--muted);border-top:1px solid var(--line);margin-top:2.5em;padding-top:1em}
.sources li{margin-bottom:6px}
/* bilingual (F-I18N): <div class="lang-ka">…</div><div class="lang-en">…</div> */
html[data-lang=ka] .lang-en,html[data-lang=en] .lang-ka{display:none}
/* labels, nav */
.labels{display:flex;gap:8px;flex-wrap:wrap;margin:30px 0}.labels a{border:1px solid var(--line);padding:4px 10px;font-size:.8rem;color:var(--muted)}.labels a:hover{color:var(--gold);border-color:var(--gold)}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:16px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0;margin:30px 0}
.post-nav a{color:var(--gold);font-size:.92rem}.post-nav .next{text-align:right}
.share{display:flex;gap:14px;font-size:.85rem;color:var(--muted)}.share a{color:var(--gold)}
.pager{display:flex;justify-content:space-between;padding:40px 0}.pager a{color:var(--gold)}
/* author (always last) */
.author-card{display:grid;grid-template-columns:120px 1fr;gap:28px;align-items:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:32px 0;margin:40px 0}
.author-card img{width:120px;height:120px;border-radius:50%;object-fit:cover;border:1px solid var(--gold)}
.author-card p{margin:4px 0;color:#c7c4b6}
/* comments */
.comments{max-width:760px;margin:0 auto 60px;font-size:.95rem}.comments h3{font-size:1.2rem}
/* footer */
.site-footer{padding:40px 0 60px;color:var(--muted);font-size:.85rem}
.site-footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}
.site-footer a{color:var(--gold)}
.site-footer ul{list-style:none;margin:0;padding:0;display:flex;gap:18px;flex-wrap:wrap}
/* static pages */
.page .post-body > p:first-of-type::first-letter{float:none;font-size:inherit;padding:0;color:inherit}
@media(max-width:720px){.search-form input{width:110px}.author-card{grid-template-columns:1fr}.post-nav{grid-template-columns:1fr}.post-nav .next{text-align:left}.hero{padding:44px 0 34px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

body.script:
//
(function(){
  var root=document.documentElement,key='ill-lang',lang='ka';
  try{var st=localStorage.getItem(key);lang=st||((navigator.language||'').slice(0,2)==='ka'?'ka':'en');}catch(e){}
  function set(l){root.setAttribute('data-lang',l);document.querySelectorAll('[data-set-lang]').forEach(function(b){b.setAttribute('aria-pressed',b.getAttribute('data-set-lang')===l)});try{localStorage.setItem(key,l)}catch(e){}}
  set(lang);
  document.querySelectorAll('[data-set-lang]').forEach(function(b){b.addEventListener('click',function(){set(b.getAttribute('data-set-lang'))})});
  // active menu item
  document.querySelectorAll('.menu a').forEach(function(a){if(location.href.indexOf(a.getAttribute('href'))>-1)a.classList.add('active')});
  // works filter (F-CATALOG)
  document.querySelectorAll('.filters button').forEach(function(btn){btn.addEventListener('click',function(){
    var f=btn.getAttribute('data-filter');btn.parentNode.querySelectorAll('button').forEach(function(x){x.setAttribute('aria-pressed',x===btn)});
    document.querySelectorAll('.work').forEach(function(w){w.style.display=(f==='all'||w.getAttribute('data-kind')===f)?'':'none'})})});
  // reading time + progress (F-PROGRESS)
  var body=document.getElementById('post-body'),rt=document.getElementById('read-time'),bar=document.getElementById('read-progress');
  if(body&&rt){var w=(body.innerText||'').split(/\s+/).length;rt.textContent=Math.max(1,Math.round(w/200))+' min';}
  if(body&&bar){window.addEventListener('scroll',function(){var r=body.getBoundingClientRect(),h=r.height-innerHeight;bar.style.width=Math.min(100,Math.max(0,(-r.top)/Math.max(1,h)*100))+'%'},{passive:true});}
})();
//
